import{esc,el}from'./engines/base.js';const RELEASE='class10-20261024';let artOverviewOpen=true;const $=id=>document.getElementById(id),courseId=document.body.dataset.course;let catalogue,course,chapter,current,engine,writing,tab='visual',request=0,visualRequest=0,answers={},checked=false,practiceMode='quiz',missionDone=new Set,chapters=new Map,state={};const KEYS={social:'samajik-darshan-v1',english:'angrezi-darshan-v1',art:'kala-darshan-v1'};try{state=JSON.parse(localStorage.getItem(KEYS[courseId])||'{}')}catch{}state={language:'bi',theme:'system',fontSize:17,lowPower:(navigator.hardwareConcurrency||4)<=2,speed:1,selectedClass:'9',lastChapter:null,lastByClass:{},complete:{},scores:{},mistakes:{},drafts:{},...state};
const save=()=>{try{localStorage.setItem(KEYS[courseId],JSON.stringify(state))}catch{}};const t=(en,hi)=>state.language==='en'?en:hi,dual=(en,hi)=>state.language==='bi'?en+' | '+hi:t(en,hi),text=v=>typeof v==='string'?v:state.language==='en'?v?.en||'':courseId==='english'&&state.language==='bi'?(v?.en||'')+'\n'+(v?.hi||''):v?.hi||v?.en||'';const label=(en,hi)=>`<span class="en">${esc(en)}</span><span class="sep"> | </span><span class="hi">${esc(hi)}</span>`;const H=(v,n=2)=>`<h${n} class="heading"><span class="en">${esc(v.en)}</span><span class="hi">${esc(v.hi)}</span></h${n}>`;const P=v=>courseId==='english'?`<p class="englishBody"><span class="en">${esc(v.en)}</span><span class="hi">${esc(v.hi)}</span></p>`:`<p>${esc(text(v))}</p>`;
const TABS=()=>[['visual',courseId==='english'?'Read and Explore':courseId==='art'?'Step-by-step Scene':'Visual Lab',courseId==='english'?'पढ़ें और समझें':courseId==='art'?'चरणबद्ध दृश्य':'दृश्य प्रयोगशाला'],['notes','Detailed Notes','विस्तृत नोट्स'],['examples',courseId==='art'?'Examples':'Solved Examples',courseId==='art'?'उदाहरण':'हल किए उदाहरण'],['practice','Practice','अभ्यास'],['sheet',courseId==='english'?'Writing Practice':courseId==='art'?'Reference Sheet':'Map / Timeline Sheet',courseId==='english'?'लेखन अभ्यास':courseId==='art'?'संदर्भ पत्रक':'मानचित्र / समयरेखा पत्रक']];
const links=[['../index.html','All subjects','सभी विषय'],['../science.html','Science','विज्ञान'],['../math/index.html','Maths','गणित'],['../social/index.html','Social Science','सामाजिक विज्ञान'],['../english/index.html','English','अंग्रेज़ी'],['../art/index.html','Art','कला']];$('subjectLinks').innerHTML=links.map(([href,en,hi])=>`<a href="${href}" ${href===`../${courseId}/index.html`?'aria-current="page"':''}>${label(en,hi)}</a>`).join('');
function preferences(){document.documentElement.dataset.language=state.language;document.documentElement.style.fontSize=state.fontSize+'px';let dark=state.theme==='dark'||state.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';$('learnTheme').textContent=dark?'☀':'🌙';$('learnLanguage').value=state.language;$('learnLowPower').checked=state.lowPower;$('doneLabel').innerHTML=label('Mark lesson complete','पाठ पूरा चिह्नित करें');$('printChapter').innerHTML=label('Print chapter','अध्याय प्रिंट करें');$('scopeMessage').textContent=courseId==='social'?dual('Requested legacy NCERT sequence. All 20 chapters are available. Historical statistics retain their textbook dates; map overlays are schematic study aids.','चुनी हुई पुरानी एनसीईआरटी संरचना। सभी 20 अध्याय उपलब्ध हैं। पुराने आँकड़ों की पाठ्यपुस्तक तिथियाँ दी गई हैं; मानचित्र परतें सांकेतिक अध्ययन-सहायक हैं।'):courseId==='english'?dual('Legacy Beehive / Moments sequence. The Fun They Had is the approved first lesson; other chapters await approval. Reader text is original study commentary.','पुरानी बीहाइव / मोमेंट्स संरचना। पहला स्वीकृत पाठ The Fun They Had है; शेष आपकी मंज़ूरी के बाद। पाठक में मौलिक अध्ययन-टिप्पणी है।'):dual('User-selected Art sequence supporting NCERT / UP Board skills. All 9 topics are available, with observation, guided drawing and printable reference sheets.','एनसीईआरटी / यूपी बोर्ड कौशल के लिए आपकी चुनी कला संरचना। सभी 9 विषयों में निरीक्षण, निर्देशित चित्रण और प्रिंट करने वाले संदर्भ पत्रक उपलब्ध हैं।')}
const originalPreferences=preferences;preferences=function(){originalPreferences();document.querySelector('.courseBadge').innerHTML=label('Class '+state.selectedClass+' · NCERT / UP Board','कक्षा '+state.selectedClass+' · एनसीईआरटी / यूपी बोर्ड');if(state.selectedClass==='10'&&courseId!=='english')$('scopeMessage').textContent=courseId==='social'?dual('Class 10 · 22 NCERT chapters · UP Board 2026–27. Map markers are study aids; illustrative chart data is labelled.','कक्षा 10 · 22 एनसीईआरटी अध्याय · यूपी बोर्ड 2026–27। मानचित्र चिह्न अध्ययन-सहायक हैं; उदाहरण के आँकड़े स्पष्ट चिह्नित हैं।'):dual('Class 10 · 12 skill-based Art lessons covering UP Board 2026–27 areas. These are teaching units, not textbook chapter numbers. The board exam also includes objective questions; this practice uses observation and description.','कक्षा 10 · यूपी बोर्ड 2026–27 के क्षेत्रों पर 12 कला पाठ। ये शिक्षण इकाइयाँ हैं, पाठ्यपुस्तक अध्याय संख्या नहीं। बोर्ड परीक्षा में वस्तुनिष्ठ प्रश्न भी हैं; यहाँ अवलोकन और वर्णन अभ्यास हैं।')};

function classAvailable(){return state.selectedClass==='9'||!!course?.classes?.[state.selectedClass]?.groups?.some(g=>g.chapters.length)}
function activeGroups(){return state.selectedClass==='9'?course.groups:course.classes?.[state.selectedClass]?.groups||[]}
function classNav(){$('classLinks').innerHTML=['LKG','UKG',...Array.from({length:12},(_,i)=>String(i+1))].map(c=>`<button data-class="${c}" aria-pressed="${state.selectedClass===c}">${c}</button>`).join('');for(let b of $('classLinks').querySelectorAll('button'))b.onclick=()=>{if(['LKG','UKG'].includes(b.dataset.class)){location.assign('../early/index.html?class='+b.dataset.class+'&subject='+(courseId==='social'?'world':courseId));return}state.selectedClass=b.dataset.class;save();classNav();preferences();if(classAvailable())selectLesson(state.lastByClass[state.selectedClass]||(state.selectedClass==='9'?state.lastChapter:null)||activeGroups()[0].chapters[0].id);else{request++;dispose();current=null;chapter=null;if($('artOverview'))$('artOverview').hidden=true;$('lessonLoading').hidden=true;history.replaceState(null,'',location.pathname+'?class='+state.selectedClass);sidebar();$('chapterMeta').textContent='';$('chapterTitle').innerHTML=label('Coming soon','जल्द आ रहा है');$('chapterGoal').textContent=dual(`Class ${state.selectedClass}: ${course.name.en} lessons are being prepared.`,`कक्षा ${state.selectedClass}: ${course.name.hi} के पाठ तैयार किए जा रहे हैं।`);$('learnActions').hidden=true;$('learnTabs').innerHTML='';for(let id of TABS().map(v=>v[0]))$('panel-'+id).hidden=true;$('lessonSources').innerHTML=''}}}
function allEntries(){return activeGroups().flatMap(g=>g.chapters.map(c=>({...c,group:g})))}
function sidebar(){let q=$('chapterSearch').value.trim().toLowerCase(),entries=allEntries(),ready=entries.filter(c=>c.available).length;let groups=activeGroups().map(g=>{let list=classAvailable()?g.chapters.filter(c=>(c.title.en+' '+c.title.hi+' '+g.title.en+' '+g.title.hi).toLowerCase().includes(q)):[];if(!list.length)return'';let open=courseId==='art'||q||list.some(c=>c.id===current?.id);return`<details ${open?'open':''}><summary>${label(g.title.en,g.title.hi)}</summary>${list.map(c=>{let value=state.complete[c.id]?1:(state.scores[c.id]||0)/(c.quizCount||8);return`<button class="${c.id===current?.id?'active':''}" data-lesson="${c.id}" ${c.id===current?.id?'aria-current="page"':''}><span>${String(c.number).padStart(2,'0')}</span><span class="chapterText"><span class="en">${esc(c.title.en)}</span><span class="hi">${esc(c.title.hi)}</span><small>${c.available?state.scores[c.id]!==undefined?dual('Best','श्रेष्ठ')+`: ${state.scores[c.id]}/${c.quizCount||8}`:dual('Ready','उपलब्ध'):dual('Coming soon','जल्द आ रहा है')}</small></span><svg viewBox="0 0 28 28" role="img" aria-label="${state.complete[c.id]?'Complete | पूर्ण':'Progress | प्रगति'}"><circle cx="14" cy="14" r="10" fill="none" stroke="var(--line)" stroke-width="3"/><circle cx="14" cy="14" r="10" fill="none" stroke="${state.complete[c.id]?'#be8c33':'var(--accent)'}" stroke-width="3" stroke-dasharray="${62.83*value} 62.83" transform="rotate(-90 14 14)"/></svg></button>`}).join('')}</details>`});$('chapterList').innerHTML=courseId==='english'&&groups.length?`<details open><summary>Beehive | बीहाइव</summary>${groups[0]}${groups[1]}</details>`+groups[2]:groups.join('');if(!groups.some(Boolean))$('chapterList').innerHTML=`<p>${dual('No chapters found.','कोई अध्याय नहीं मिला।')}</p>`;for(let b of $('chapterList').querySelectorAll('[data-lesson]'))b.onclick=()=>{if($('learnDrawer').open)$('learnDrawer').close();selectLesson(b.dataset.lesson)};let done=entries.filter(c=>c.available&&state.complete[c.id]).length;$('learnProgress').max=Math.max(1,ready);$('learnProgress').value=done;$('learnProgressText').textContent=`${done} / ${ready} ${dual('released lessons complete','उपलब्ध पाठ पूर्ण')}`}
function renderArtOverview(){if(courseId!=='art'||!course)return;let box=$('artOverview');if(!box){box=document.createElement('section');box.id='artOverview';$('lessonLoading').before(box)}box.hidden=!classAvailable();box.innerHTML=`<button id="allArtTopics" aria-expanded="${artOverviewOpen}" aria-controls="artTopicGrid">${label('All '+allEntries().length+' Art Topics','चित्रकला के सभी '+allEntries().length+' विषय')} ${artOverviewOpen?'−':'+'}</button><div id="artTopicGrid" ${artOverviewOpen?'':'hidden'}>${H({en:'Your Complete Art Book',hi:'आपकी पूरी चित्रकला पुस्तक'},2)}<div class="artTopicGroups">${activeGroups().map(g=>`<article>${H(g.title,3)}${g.chapters.map(c=>`<button data-art-topic="${c.id}" aria-current="${current?.id===c.id?'page':'false'}">${label(c.title.en,c.title.hi)}<small>${dual('Notes · Drawing · Practice · Reference sheet','नोट्स · चित्र · अभ्यास · संदर्भ पत्रक')}</small></button>`).join('')}</article>`).join('')}</div></div>`;$('allArtTopics').onclick=()=>{artOverviewOpen=!artOverviewOpen;renderArtOverview()};for(let b of box.querySelectorAll('[data-art-topic]'))b.onclick=async()=>{artOverviewOpen=false;await selectLesson(b.dataset.artTopic);$('chapterTitle').focus();$('chapterTitle').scrollIntoView({block:'start'})}}
function dispose(){visualRequest++;engine?.destroy();writing?.destroy();engine=null;writing=null}
async function selectLesson(id){let entry=allEntries().find(c=>c.id===id)||allEntries()[0],token=++request;id=entry.id;dispose();current=entry;chapter=null;state.lastByClass[state.selectedClass]=entry.id;if(state.selectedClass==='9')state.lastChapter=entry.id;save();history.replaceState(null,'',location.pathname+'?class='+state.selectedClass+'#'+entry.id);classNav();sidebar();renderArtOverview();$('learnActions').hidden=!entry.available;$('lessonSources').innerHTML='';$('chapterMeta').textContent=dual('Class','कक्षा')+' '+state.selectedClass+' · '+dual(entry.group.title.en,entry.group.title.hi)+` · ${dual('Chapter','अध्याय')} ${entry.number}`;$('chapterTitle').innerHTML=`<span class="en">${esc(entry.title.en)}</span><span class="hi">${esc(entry.title.hi)}</span>`;$('chapterGoal').textContent='';for(let[id]of TABS())$('panel-'+id).hidden=true;$('learnTabs').innerHTML='';if(!entry.available){$('lessonLoading').hidden=false;$('lessonLoading').innerHTML=`<article class="emptyLesson">${H({en:'Coming Soon',hi:'जल्द आ रहा है'})}${P({en:'This chapter is listed for planning. Its lessons will be added after your approval.',hi:'यह अध्याय योजना के लिए सूची में है। आपकी मंज़ूरी के बाद इसके पाठ जोड़े जाएँगे।'})}</article>`;return}$('lessonLoading').hidden=false;$('lessonLoading').textContent=dual('Loading lesson…','पाठ खुल रहा है…');try{let data=chapters.get(id);if(!data){let r=await fetch('../learn/data/'+id+'.json?v='+RELEASE,{cache:'no-cache'});if(!r.ok)throw Error('Chapter unavailable');data=await r.json();chapters.set(id,data)}if(token!==request)return;chapter=data;tab='visual';answers={};checked=false;missionDone=new Set;renderChapter()}catch(e){if(token!==request)return;$('lessonLoading').textContent=dual('Could not load this lesson. Please reopen while connected.','पाठ नहीं खुला। इंटरनेट जोड़कर फिर खोलें।');console.error(e)}}
function renderTabs(){let ids=TABS().map(v=>v[0]);$('learnTabs').innerHTML=TABS().map(([id,en,hi])=>`<button role="tab" class="learnTab" id="learn-tab-${id}" aria-controls="panel-${id}" aria-selected="${id===tab}" tabindex="${id===tab?0:-1}">${label(en,hi)}</button>`).join('');for(let id of ids){$('panel-'+id).hidden=tab!==id;$('panel-'+id).setAttribute('aria-labelledby','learn-tab-'+id);let b=$('learn-tab-'+id);b.onclick=()=>switchTab(id);b.onkeydown=e=>{let i=ids.indexOf(id),next=e.key==='ArrowRight'?ids[(i+1)%ids.length]:e.key==='ArrowLeft'?ids[(i+ids.length-1)%ids.length]:e.key==='Home'?ids[0]:e.key==='End'?ids.at(-1):null;if(next){e.preventDefault();switchTab(next);$('learn-tab-'+next).focus()}}}}
function switchTab(id){tab=id;if(id!=='visual'&&engine?.playing){engine.pause();playing(false)}renderTabs();if(id==='sheet'&&courseId==='english'&&!writing)renderWriting()}
function renderChapter(){$('lessonLoading').hidden=true;$('chapterGoal').textContent=text(chapter.goal);$('lessonDone').checked=!!state.complete[chapter.id];renderTabs();renderNotes();renderExamples();renderPractice();renderSheet();renderVisual();$('lessonSources').innerHTML=label('Sources & further reading','स्रोत और आगे पढ़ें')+'<br>'+chapter.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)}</a>`).join('')}
function artElements(){return `<article class="learnCard">${H({en:'Elements of Art — Visual Guide',hi:'कला के तत्त्व — दृश्य परिचय'})}<div class="elementExamples">${[['Line','रेखा','<path d="M10 50Q50 5 90 50" fill="none" stroke="#356c53" stroke-width="4"/>'],['Shape','आकार','<rect x="25" y="15" width="50" height="50" fill="#97bda5"/>'],['Form','रूप','<defs><radialGradient id="formTone" cx="30%" cy="25%"><stop stop-color="#f6ebd6"/><stop offset="1" stop-color="#70432f"/></radialGradient></defs><circle cx="50" cy="40" r="30" fill="url(#formTone)"/>'],['Tone','टोन','<path d="M10 20H90V60H10Z" fill="#ded3ba"/><path d="M35 20H90V60H35Z" fill="#b39975"/><path d="M60 20H90V60H60Z" fill="#70432f"/>'],['Texture','बनावट','<path d="M20 10L10 60M35 10L25 60M50 10L40 60M65 10L55 60M80 10L70 60M10 25H85M10 45H85" stroke="#86704c"/>'],['Colour','रंग','<circle cx="30" cy="30" r="20" fill="#b94e43"/><circle cx="65" cy="30" r="20" fill="#d4af48"/><circle cx="48" cy="57" r="20" fill="#527ba1"/>']].map(([en,hi,d])=>`<div><svg viewBox="0 0 100 85" role="img" aria-label="${en} | ${hi}">${d}</svg>${label(en,hi)}</div>`).join('')}</div></article>`}function renderNotes(){$('panel-notes').innerHTML=(courseId==='art'?artElements():'')+H({en:'Detailed Notes',hi:'विस्तृत नोट्स'})+chapter.notes.map(n=>`<article class="learnCard">${H(n.title)}${P(n.body)}${n.question?`<aside class="intextQuestion"><strong>${dual("Think about it","सोचकर उत्तर दें")}</strong>${P(n.question)}</aside>`:""}</article>`).join('')+(chapter.vocabulary?`<article class="learnCard">${H({en:'Difficult Words & Meanings',hi:'कठिन शब्द और अर्थ'})}<div class="wordList">${chapter.vocabulary.map(v=>`<div><strong>${esc(v.word)}</strong><p>${esc(v.meaning)}</p><p class="hi">${esc(v.hi)}</p></div>`).join('')}</div><details><summary>${label('All reader words with meanings','पाठक के सभी शब्दों के अर्थ')} (${Object.keys(chapter.lexicon).length})</summary><div class="wordList">${Object.entries(chapter.lexicon).sort(([a],[b])=>a.localeCompare(b)).map(([w,v])=>`<div><strong>${esc(w)}</strong><p>${esc(v.meaning)}</p><p class="hi">${esc(v.hi)}</p></div>`).join('')}</div></details></article>`:'')+(courseId==='english'?`<article class="learnCard">${H({en:'Important Study Extract',hi:'महत्त्वपूर्ण अध्ययन अंश'})}<p class="scopeNote">${dual('Original companion text, not a quotation from the story.','मौलिक अध्ययन-सहायक पाठ, मूल कहानी का उद्धरण नहीं।')}</p>${P(chapter.extractQuestions[0].source)}${P(chapter.extractQuestions[0].answer)}</article>`:courseId==='art'?`<article class="learnCard">${H({en:'Common Mistakes',hi:'सामान्य गलतियाँ'})}${P(chapter.commonMistakes||{en:'Avoid a flat top ellipse, a heavy outline everywhere and one uniform grey tone. Keep the body symmetrical before shading, and reserve the highlight instead of filling it dark.',hi:'ऊपरी दीर्घवृत्त को सपाट, हर ओर रूपरेखा को भारी और पूरे चित्र को एक जैसा धूसर न बनाएँ। छायांकन से पहले वस्तु का संतुलन जाँचें और चमक वाले भाग को गहरा भरने से बचें।'})}</article>`:'')}
async function renderExamples(){if(courseId==='art'){let own=chapter;$('panel-examples').innerHTML=H({en:'Finished Drawing Examples',hi:'पूर्ण चित्रों के उदाहरण'})+`<div class="artExamples">${chapter.examples.map((e,i)=>`<article class="artExample">${H(e.title,3)}<canvas data-example="${i}" width="600" height="400" role="img" aria-label="${esc(e.level+' '+chapter.title.en)} "></canvas><p><strong>${dual('Done well','क्या अच्छा है')}:</strong> ${esc(text(e.well))}</p><p><strong>${dual('Could improve','क्या सुधारें')}:</strong> ${esc(text(e.improve))}</p></article>`).join('')}</div>`;let{drawArtwork}=await import('./engines/art.js');if(chapter!==own)return;for(let c of $('panel-examples').querySelectorAll('canvas')){let i=+c.dataset.example;drawArtwork(c,chapter,chapter.artTopic?9:[4,6,9][i],['Beginner','Intermediate','Good'][i])}}else $('panel-examples').innerHTML=H({en:'Solved Examples',hi:'हल किए उदाहरण'})+chapter.examples.map(e=>`<article class="learnCard">${H(e.title,3)}${P(e.question)}<ol>${e.steps.map(s=>`<li>${esc(text(s))}</li>`).join('')}</ol><p class="formula">${esc(text(e.answer))}</p></article>`).join('')}
const question=(q,i)=>`<div class="questionBlock">${P({en:(i+1)+'. '+q.question.en,hi:(i+1)+'. '+q.question.hi})}<details><summary>${label('Show solution','उत्तर देखें')}</summary>${P(q.answer)}</details></div>`;
function renderPractice(){if(courseId==='art'){$('panel-practice').innerHTML=H({en:'Observe, Explain & Describe',hi:'देखें, समझाएँ और वर्णन करें'})+`<article class="learnCard">${H({en:'5 Observation Questions',hi:'5 अवलोकन प्रश्न'},3)}${chapter.observations.map(question).join('')}</article><article class="learnCard">${H({en:'Technique Questions',hi:'तकनीक के प्रश्न'},3)}${chapter.shortAnswers.map(question).join('')}</article><article class="learnCard">${H({en:'Describe in 5 Lines',hi:'5 पंक्तियों में वर्णन'},3)}${P(chapter.description.question)}<label>${label('Your description','आपका वर्णन')}<textarea id="artDescription" rows="6"></textarea></label><details><summary>${label('Show model description','आदर्श वर्णन देखें')}</summary>${P(chapter.description.answer)}</details></article>`;$('artDescription').value=state.drafts['describe-'+chapter.id]||'';$('artDescription').oninput=e=>{state.drafts['describe-'+chapter.id]=e.target.value;save()};return}
 let mistakes=Object.entries(state.mistakes).filter(([id])=>state.selectedClass==='10'?id.startsWith('ten-'):!id.startsWith('ten-'));$('panel-practice').innerHTML=H({en:'Practice',hi:'अभ्यास'})+`<nav class="practiceModes" role="tablist" aria-label="Practice modes | अभ्यास के प्रकार"><button role="tab" id="mode-quiz" aria-controls="practiceQuestions" aria-selected="${practiceMode==='quiz'}" tabindex="${practiceMode==='quiz'?0:-1}">${label('Questions','प्रश्न')}</button><button role="tab" id="mode-mistakes" aria-controls="practiceMistakes" aria-selected="${practiceMode==='mistakes'}" tabindex="${practiceMode==='mistakes'?0:-1}">${label('Mistake Notebook','गलतियों की नोटबुक')} (${mistakes.length})</button></nav><div id="practiceQuestions" role="tabpanel" aria-labelledby="mode-quiz" ${practiceMode==='quiz'?'':'hidden'}><article class="learnCard">${H({en:chapter.quiz.length+' Quick MCQs',hi:chapter.quiz.length+' बहुविकल्पीय प्रश्न'},3)}<form class="quizForm" id="learnQuiz">${chapter.quiz.map((q,i)=>`<fieldset class="quizSet"><legend>${i+1}. ${esc(text(q.question))}</legend>${q.options.map((o,j)=>`<label class="quizOption ${checked?(j===q.correct?'correctChoice':answers[i]===j?'wrongChoice':''):''}"><span><input type="radio" name="learn-q-${i}" data-question="${i}" value="${j}" ${answers[i]===j?'checked':''} ${checked?'disabled':''}> ${esc(text(o.text))}</span>${checked?`<span class="quizReason">${j===q.correct?'✓ ':answers[i]===j?'✗ ':''}${esc(text(o.reason))}</span>`:''}</label>`).join('')}</fieldset>`).join('')}<p id="learnScore" role="status">${checked?dual('Score','अंक')+`: ${chapter.quiz.reduce((n,q,i)=>n+(q.correct===answers[i]),0)} / ${chapter.quiz.length}`:''}</p><button class="primary" type="submit" ${checked?'disabled':''}>${label('Check answers','उत्तर जाँचें')}</button> <button type="button" id="learnRetry">${label('Try again','फिर प्रयास करें')}</button></form></article><article class="learnCard">${H({en:'Short Answers',hi:'लघु उत्तरीय प्रश्न'},3)}${chapter.shortAnswers.map(question).join('')}</article>${['sourceQuestions','mapQuestions','extractQuestions'].filter(k=>chapter[k]).map(k=>`<article class="learnCard">${H(k==='sourceQuestions'?{en:'2 Source-based Questions',hi:'2 स्रोत आधारित प्रश्न'}:k==='mapQuestions'?{en:'2 Map-based Questions',hi:'2 मानचित्र आधारित प्रश्न'}:{en:'2 Extract-based Questions',hi:'2 अंश आधारित प्रश्न'},3)}${chapter[k].map((q,i)=>(q.source?`<div class="sourceExcerpt"><small>${dual('Original teaching extract','मौलिक शिक्षण अंश')}</small>${P(q.source)}</div>`:'')+question(q,i)).join('')}</article>`).join('')}${chapter.grammar?`<article class="learnCard">${H(chapter.grammar.title,3)}${P(chapter.grammar.prompt)}${chapter.grammar.items.map(question).join('')}</article>`:''}</div><div id="practiceMistakes" role="tabpanel" aria-labelledby="mode-mistakes" ${practiceMode==='mistakes'?'':'hidden'}>${mistakes.length?mistakes.map(([id,m])=>`<article class="learnCard">${H(m.title,3)}${P(m.question)}<p>✓ ${esc(text(m.answer))}</p>${P(m.reason)}<button data-forget="${id}">${label('Understood — remove','समझ गया — हटाएँ')}</button></article>`).join(''):`<article class="learnCard">${dual('No mistakes saved yet.','अभी कोई गलती सुरक्षित नहीं है।')}</article>`}</div>`;
 for(let mode of['quiz','mistakes']){$('mode-'+mode).onclick=()=>{practiceMode=mode;renderPractice()};$('mode-'+mode).onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();practiceMode=e.key==='Home'?'quiz':e.key==='End'?'mistakes':practiceMode==='quiz'?'mistakes':'quiz';renderPractice();$('mode-'+practiceMode).focus()}}}for(let b of $('panel-practice').querySelectorAll('[data-forget]'))b.onclick=()=>{delete state.mistakes[b.dataset.forget];save();renderPractice()};for(let r of $('learnQuiz').querySelectorAll('input'))r.onchange=()=>answers[r.dataset.question]=+r.value;$('learnQuiz').onsubmit=e=>{e.preventDefault();checked=true;let score=chapter.quiz.reduce((n,q,i)=>n+(q.correct===answers[i]),0);state.scores[chapter.id]=Math.max(score,state.scores[chapter.id]||0);chapter.quiz.forEach((q,i)=>{if(answers[i]!==undefined&&answers[i]!==q.correct)state.mistakes[chapter.id+':'+i]={title:chapter.title,question:q.question,answer:q.options[q.correct].text,reason:q.options[q.correct].reason}});save();sidebar();renderPractice();$('learnScore').scrollIntoView({block:'center'})};$('learnRetry').onclick=()=>{answers={};checked=false;renderPractice();$('learnQuiz').querySelector('input').focus()}}
function playing(on){let b=$('enginePlay');if(b)b.innerHTML=label(on?'⏸ Pause':'▶ Play',on?'⏸ रोकें':'▶ चलाएँ')}
function changed(metrics){if(!chapter)return;chapter.missions.forEach((m,i)=>{if(Number(metrics[m.key]||0)>=m.min)missionDone.add(i);let e=$('learnMission-'+i);if(e){e.classList.toggle('done',missionDone.has(i));e.innerHTML=(missionDone.has(i)?'✓ ':'○ ')+esc(text(m.label))}})}
function engineContext(){return{chapter,text,t,dual,label,H,speed:state.speed,lowPower:state.lowPower,live:s=>{if($('learnLive'))$('learnLive').textContent=s},changed,playing,reload:renderVisual,draft:state.drafts[chapter.id]||'',saveDraft:v=>{state.drafts[chapter.id]=v;save()}}}
async function renderVisual(){let own=chapter,renderId=++visualRequest;engine?.destroy();engine=null;missionDone=new Set;let speed=courseId==='art'?[.5,1,2]:[.25,.5,1,2];$('panel-visual').innerHTML=`<div class="missionsBox">${H({en:'Try This',hi:'यह करके देखें'},3)}<ul class="learnMissions">${chapter.missions.map((m,i)=>`<li id="learnMission-${i}">○ ${esc(text(m.label))}</li>`).join('')}</ul></div><div class="learnLab"><div id="learnEngine"></div><p class="liveLearn" id="learnLive" role="status" aria-live="polite"></p><div class="engineToolbar"><button id="enginePlay">${label('▶ Play','▶ चलाएँ')}</button><button id="engineRestart">${label('↺ Restart','↺ पुनः शुरू')}</button><button id="engineReset">${label('⟳ Reset view','⟳ मूल दृश्य')}</button><label><input type="checkbox" id="engineLabels" checked> ${label('Show labels','नाम दिखाएँ')}</label></div><div class="engineSpeed">${speed.map(s=>`<button data-speed="${s}" aria-pressed="${state.speed===s}">${s}×</button>`).join('')}</div></div><div class="learnWhy"><button id="learnWhy" aria-expanded="false" aria-controls="learnWhyText">${label('Why?','ऐसा क्यों?')}</button><p id="learnWhyText" hidden>${esc(text(chapter.why))}</p><button id="learnReadNotes">${label('Read detailed notes →','विस्तृत नोट्स पढ़ें →')}</button></div>`;$('learnWhy').onclick=()=>{$('learnWhyText').hidden=!$('learnWhyText').hidden;$('learnWhy').setAttribute('aria-expanded',String(!$('learnWhyText').hidden))};$('learnReadNotes').onclick=()=>switchTab('notes');try{let file=chapter.engine==='step'?'art':chapter.engine,mod=await import('./engines/'+file+'.js?v='+RELEASE);if(chapter!==own||renderId!==visualRequest)return;let instance=new mod.default($('learnEngine'),engineContext());engine=instance;if(instance.ready)await instance.ready;if(chapter!==own||renderId!==visualRequest||engine!==instance){instance.destroy();return}$('enginePlay').onclick=()=>playing(engine.pause());$('engineRestart').onclick=()=>renderVisual();$('engineReset').onclick=()=>engine.resetView();$('engineLabels').onchange=e=>engine.setLabels(e.target.checked);for(let b of $('panel-visual').querySelectorAll('[data-speed]'))b.onclick=()=>{state.speed=+b.dataset.speed;save();engine.setSpeed(state.speed);for(let el of $('panel-visual').querySelectorAll('[data-speed]'))el.setAttribute('aria-pressed',String(+el.dataset.speed===state.speed))}}catch(e){if(chapter!==own||renderId!==visualRequest)return;$('learnLive').textContent=dual('This activity could not load. Reopen while connected.','यह गतिविधि नहीं खुली। इंटरनेट जोड़कर फिर खोलें।');console.error(e)}}
async function renderWriting(){let own=chapter,mod=await import('./engines/writing.js');if(chapter!==own)return;writing?.destroy();$('panel-sheet').innerHTML=H({en:'Writing Practice',hi:'लेखन अभ्यास'})+'<article class="learnCard" id="writingEngine"></article>';writing=new mod.default($('writingEngine'),{...engineContext(),live:()=>{},changed:()=>{}})}
async function renderSheet(){if(courseId==='english'){$('panel-sheet').innerHTML=H({en:'Writing Practice',hi:'लेखन अभ्यास'});return}let own=chapter;$('panel-sheet').innerHTML=`<div class="printTools"><button id="printSheet">${label('Print this one-page sheet','यह 1-पृष्ठ पत्रक प्रिंट करें')}</button></div><article class="sheetPage"><header class="sheetHeader">${H(chapter.title)}<p>${dual('Name','नाम')}: ____________________ ${dual('Class','कक्षा')}: ${state.selectedClass} ${dual('Date','दिनांक')}: __________</p></header><div id="sheetContent"></div><p class="sheetFoot">${dual('Original study aid; use your prescribed textbook alongside.','मौलिक अध्ययन-सहायक; निर्धारित पाठ्यपुस्तक के साथ उपयोग करें।')}</p></article>`;$('printSheet').onclick=()=>print('sheet');if(chapter.engine==='timeline'){$('sheetContent').innerHTML=`<div class="timelineSheet">${chapter.timeline.map(e=>`<article><strong>${esc(e.date)}</strong>${H(e.title,3)}<p>${esc(text(e.effect))}</p></article>`).join('')}</div><p>${dual('Add one cause and one consequence to any 2 events.','किन्हीं 2 घटनाओं के 1 कारण और 1 परिणाम जोड़ें।')}</p>`}else if(chapter.engine==='map'){let data=await fetch('../learn/data/map-base.json').then(r=>r.json());if(chapter!==own)return;$('sheetContent').innerHTML=`<div class="mapSheet"><svg viewBox="0 0 800 760" role="img" aria-label="India outline worksheet | भारत रूपरेखा कार्यपत्रक"><g fill="#edf2e4" stroke="#344a3b" stroke-width=".6">${data.paths.map(p=>`<path d="${p.d}"/>`).join('')}</g><path d="M350 60V680 M60 330H660" stroke="#9b8559" stroke-width="1" stroke-dasharray="6 6" fill="none"/></svg></div><ol>${chapter.mapQuestions.map(q=>`<li>${esc(text(q.question))}</li>`).join('')}</ol><p class="sheetFoot">© Survey of India · ${esc(data.source.url)} · ${dual('Educational, non-commercial use. Dashed guide lines show 82.5°E and 23.5°N.','शैक्षिक, गैर-वाणिज्यिक उपयोग। बिंदीदार मार्गदर्शक रेखाएँ 82.5°E और 23.5°N दिखाती हैं।')}</p>`}else if(chapter.engine==='diagram'){$('sheetContent').innerHTML=`<div class="diagramSheet">${chapter.diagram.nodes.map(n=>`<article>${H(n.title,3)}${P(n.body)}<small>${(n.next||[]).map(id=>esc(text(chapter.diagram.nodes.find(x=>x.id===id)?.title))).join(' → ')}</small></article>`).join('')}</div>`}else if(chapter.engine==='chart'){$('sheetContent').innerHTML=`${H(chapter.chart.title||chapter.title,3)}<table><thead><tr><th>${dual('Category','श्रेणी')}</th><th>${esc(text(chapter.chart.unit))}</th></tr></thead><tbody>${chapter.chart.rows.map(r=>`<tr><td>${esc(text(r.label))}</td><td>${r.value}</td></tr>`).join('')}</tbody></table>${P(chapter.chart.source)}${P(chapter.chart.note)}<div class="chartWorksheet">${dual('Draw a bar chart using the table. Label both axes and write one comparison.','तालिका से दंड आलेख बनाएँ। दोनों अक्षों के नाम और 1 तुलना लिखें।')}</div>`}else{let{drawArtwork}=await import('./engines/art.js');if(chapter!==own)return;let images=[];for(let i=0;i<chapter.artStepTips.length;i++){let c=document.createElement('canvas');c.width=300;c.height=200;drawArtwork(c,chapter,i);images.push(c.toDataURL('image/png'))}$('sheetContent').innerHTML=`<div class="artSheetGrid">${chapter.artStepTips.map((s,i)=>`<div><img src="${images[i]}" alt="Step ${i+1} | चरण ${i+1}"><p><strong>${i+1}. ${esc(text(s.title))}</strong><br>${esc(text(s.tip))}</p></div>`).join('')}</div><div class="artPalette">${chapter.palette.map(p=>`<button type="button" style="--swatch:${p.color}"><i></i>${esc(text(p.name))}</button>`).join('')}</div><p>${esc(text(chapter.why))}</p>`}}
